#include <filesystem>
#include <mutex>
namespace fs = std::filesystem;

std::mutex m;
void append(fs::path const& p, std::string const& line) {
  std::scoped_lock lock(m);                  // owns lock/unlock pairing
  std::ofstream out(p, std::ios::app);       // owns open/close pairing
  out << line << '\n';
}

